#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, d;
    scanf("%d %d", &n, &d);
    vector<ll> cnt(d, 0);
    for (int i = 0; i < n; i++) {
        ll v;
        scanf("%lld", &v);
        cnt[((v % d) + d) % d]++;
    }
    ll ans = 0;
    // Enumerate remainder triples a <= b <= c with a + b + c == 0 (mod d).
    for (int a = 0; a < d; a++)
        for (int b = a; b < d; b++) {
            int c = ((-(a + b)) % d + d) % d;
            if (c < b) continue;
            if (a == b && b == c) ans += cnt[a] * (cnt[a] - 1) * (cnt[a] - 2) / 6;
            else if (a == b) ans += cnt[a] * (cnt[a] - 1) / 2 * cnt[c];
            else if (b == c) ans += cnt[a] * (cnt[b] * (cnt[b] - 1) / 2);
            else ans += cnt[a] * cnt[b] * cnt[c];
        }
    printf("%lld\n", ans);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken()), d = Integer.parseInt(st.nextToken());
        long[] cnt = new long[d];
        for (int i = 0; i < n; i++) cnt[(int) Math.floorMod(Long.parseLong(st.nextToken()), (long) d)]++;
        long ans = 0;
        // Enumerate remainder triples a <= b <= c with a + b + c == 0 (mod d).
        for (int a = 0; a < d; a++)
            for (int b = a; b < d; b++) {
                int c = Math.floorMod(-(a + b), d);
                if (c < b) continue;
                if (a == b && b == c) ans += cnt[a] * (cnt[a] - 1) * (cnt[a] - 2) / 6;
                else if (a == b) ans += cnt[a] * (cnt[a] - 1) / 2 * cnt[c];
                else if (b == c) ans += cnt[a] * (cnt[b] * (cnt[b] - 1) / 2);
                else ans += cnt[a] * cnt[b] * cnt[c];
            }
        System.out.println(ans);
    }
}
